WITH filtered AS (SELECT *, CASE WHEN brand IN ('Umbrella', 'Acme') THEN 'Core' ELSE 'Other' END AS brand_group, COALESCE(brand, 'UNKNOWN') AS brand_filled FROM products WHERE launch_date > TO_DATE('2023-09-28') AND brand IS NOT NULL AND SIZE(tags) >= 1) SELECT supplier_id, brand FROM filtered EXCEPT ALL SELECT supplier_id, brand FROM products WHERE launch_date BETWEEN '2023-07-01' AND '2023-10-01';
